  "content": "#!/usr/bin/env python3
"""Frozen executable benchmark runner.

Reads evaluation.json (manifest) and data/*.json (grader assets), runs each
declared item against the scoped evaluation context (one candidate model),
grades deterministically, and writes the item results to --output.

All grading is local and deterministic; it depends only on the candidate's
response text, never on candidate identity or reference labels.
"""
import argparse
import json
import os
import re
import subprocess
import sys
import tempfile
import textwrap

BASE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, "/workspace")


def load_assets():
    def j(path):
        with open(os.path.join(BASE, path), "r", encoding="utf-8") as f:
            return json.load(f)
    data = {}
    for name in ("reasoning", "coding", "cowork"):
        try:
            data[name] = j(os.path.join("data", name + ".json"))
        except FileNotFoundError:
            data[name] = {}
    gr = {}
    for name in data:
        items = data[name]
        if isinstance(items, dict):
            items = items.get("questions", [])
        for q in items:
            gr[q["id"]] = q
    return gr


def normalize(s):
    s = s.replace(" ", " ")
    s = s.replace("$", "").replace("\n", " ").replace("\t", " ")
    s = re.sub(r"\s+", " ", s)
    s = s.strip()
    return s


def norm_math(s):
    s = s.strip()
    s = s.replace("\\left", "").replace("\\right", "")
    s = re.sub(r"\s+", "", s)
    s = s.replace("$", "")
    s = s.replace("\,", "").replace("\;", "").replace("\quad", "").replace("\,", "")
    return s


# ---------------- grading helpers ----------------

def extract_boxed(text, fallback_last_line=True):
    m = re.findall(r"\\boxed\{((?:[^{}]|\{[^{}]*\})*)\}", text)
    if m:
        return m[-1]
    # \boxed with nested up to a few levels handled by balance scan
    best = None
    for mm in re.finditer(r"\\boxed", text):
        i = mm.end()
        if i < len(text) and text[i] == "{":
            depth = 0
            j = i
            while j < len(text):
                if text[j] == "{":
                    depth += 1
                elif text[j] == "}":
                    depth -= 1
                    if depth == 0:
                        best = text[i + 1:j]
                        break
                j += 1
    if best is not None:
        return best
    if fallback_last_line:
        lines = [l.strip() for l in text.strip().splitlines() if l.strip()]
        if lines:
            return lines[-1]
    return None


def extract_mc_letter(text):
    t = normalize(text)
    # explicit answer markers
    for pat in (r"answer\s*(?:is|:)?\s*([A-HJ-Z])",
                r"option\s*([A-HJ-Z])",
                r"\b([A-HJ-Z])\)",
                r"\(\s*([A-HJ-Z])\s*\)"):
        m = re.search(pat, t, re.IGNORECASE)
        if m:
            return m.group(1).upper()
    # last standalone capital letter (excluding common words)
    caps = re.findall(r"\b[A-HJ-Z]\b", t)
    if caps:
        return caps[-1].upper()
    return None


def extract_final_number_or_text(text):
    return normalize(text)


# ---------------- grader builders ----------------

def make_mc_grader(gold):
    def g(text):
        got = extract_mc_letter(text)
        return 1.0 if (got is not None and got.upper() == gold.strip().upper()) else 0.0
    return g


def make_match_grader(gold, mode="contains_tok"):
    gn = normalize(gold)
    def g(text):
        t = normalize(text)
        if mode == "contains":
            return 1.0 if gn in t else 0.0
        elif mode == "equals":
            return 1.0 if gn == t else 0.0
        else:  # contains_tok: gold appears as substring; also try boxed
            bx = extract_boxed(text, fallback_last_line=True)
            if bx is not None and normalize(bx) == gn:
                return 1.0
            return 1.0 if gn in t else 0.0
    return g


def make_math_grader(gold):
    gn = norm_math(gold)
    def g(text):
        bx = extract_boxed(text, fallback_last_line=True)
        if bx is None:
            return 0.0
        return 1.0 if norm_math(bx) == gn else 0.0
    return g


def _run_python_in_subprocess(prog, timeout=8):
    """Run a small self-contained python program; return (ok, output)."""
    try:
        r = subprocess.run(
            [sys.executable, "-c", prog],
            capture_output=True, text=True, timeout=timeout,
            cwd=tempfile.gettempdir(),
        )
        return True, (r.stdout or "") + (r.stderr or "")
    except subprocess.TimeoutExpired:
        return False, "TIMEOUT"
    except Exception as e:
        return False, "EXC:%s" % e


def extract_code_block(text):
    m = re.search(r"```(?:python|py)?\s*\n(.*?)```", text, re.DOTALL)
    if m:
        return m.group(1)
    m = re.search(r"```(.*?)```", text, re.DOTALL)
    if m:
        return m.group(1)
    # fallback: whole text
    return text


def make_func_grader(tests, fn="f"):
    def g(text):
        code = extract_code_block(text)
        harness = []
        harness.append(code)
        harness.append("\n# --- harness ---\n")
        passed = 0
        for t in tests:
            args = t.get("args", [])
            expected = t.get("expected")
            call = "%s(%s)" % (fn, ", ".join(repr(a) for a in args))
            harness.append("try:\n    _r = %s\nexcept Exception as e:\n    _r = '__ERR__'\n" % call)
            harness.append("print(repr(_r))\n")
        prog = "\n".join(harness)
        ok, out = _run_python_in_subprocess(prog)
        if not ok:
            return 0.0
        lines = [l for l in out.splitlines() if l]
        for i, t in enumerate(tests):
            if i >= len(lines):
                break
            got = lines[i]
            exp = repr(t.get("expected"))
            if got == exp:
                passed += 1
            else:
                # numeric tolerance for floats
                try:
                    gv = float(got)
                    ev = float(t.get("expected"))
                    if abs(gv - ev) < 1e-6:
                        passed += 1
                except Exception:
                    pass
        return passed / float(len(tests)) if tests else 0.0
    return g


def make_fix_grader(tests, fn="f"):
    # tests are full expressions to eval; return fraction that pass
    def g(text):
        code = extract_code_block(text)
        checks = []
        for t in tests:
            checks.append("try:\n    _r = (%s)\nexcept Exception as e:\n    _r = '__ERR__'\nprint(repr(_r))\n" % t)
        prog = code + "\n# --- harness ---\n" + "\n".join(checks)
        ok, out = _run_python_in_subprocess(prog)
        if not ok:
            return 0.0
        lines = [l for l in out.splitlines() if l]
        passed = 0
        for i, t in enumerate(tests):
            if i < len(lines) and lines[i] == "True":
                passed += 1
        return passed / float(len(tests)) if tests else 0.0
    return g


def _check(c, text):
    kind = c["kind"]
    t = text
    tl = t.lower()
    if kind == "contains":
        return 1.0 if c["value"].lower() in tl else 0.0
    if kind == "not_contains":
        return 1.0 if c["value"].lower() not in tl else 0.0
    if kind == "contains_all":
        return 1.0 if all(v.lower() in tl for v in c["values"]) else 0.0
    if kind == "contains_none":
        return 1.0 if all(v.lower() not in tl for v in c["values"]) else 0.0
    if kind == "word_count_le":
        return 1.0 if len(re.findall(r"\S+", text)) <= c["value"] else 0.0
    if kind == "word_count_ge":
        return 1.0 if len(re.findall(r"\S+", text)) >= c["value"] else 0.0
    if kind == "exact_norm":
        return 1.0 if normalize(text) == c["value"] else 0.0
    if kind == "json_keys":
        m = re.search(r"\{.*\}", text, re.DOTALL)
        if not m:
            return 0.0
        try:
            obj = json.loads(m.group(0))
        except Exception:
            return 0.0
        return 1.0 if all(k in obj for k in c["keys"]) else 0.0
    if kind == "count":
        return 1.0 if tl.count(c["value"].lower()) == c["n"] else 0.0
    if kind == "numeric_eq":
        nums = re.findall(r"-?\d+(?:\.\d+)?", text)
        target = c["value"]
        return 1.0 if any(abs(float(n) - target) < 1e-6 for n in nums) else 0.0
    if kind == "regex":
        return 1.0 if re.search(c["pattern"], text, re.IGNORECASE) else 0.0
    return 0.0


def make_checks_grader(checks):
    def g(text):
        return sum(_check(c, text) for c in checks) / float(len(checks))
    return g


def build_grader(spec):
    typ = spec.get("type")
    if typ == "mc":
        return make_mc_grader(spec["gold"])
    if typ == "match":
        return make_match_grader(spec["gold"], spec.get("mode", "contains_tok"))
    if typ == "math":
        return make_math_grader(spec["gold"])
    if typ == "func":
        return make_func_grader(spec.get("tests", []), spec.get("fn", "f"))
    if typ == "fix":
        return make_fix_grader(spec.get("tests", []), spec.get("fn", "f"))
    if typ == "checks":
        return make_checks_grader(spec.get("checks", []))
    raise ValueError("unknown grader type: %s" % typ)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--context", required=True)
    ap.add_argument("--output", required=True)
    args = ap.parse_args()

    from research_sdk import Client
    c = Client(args.context)

    manifest = json.load(open(os.path.join(BASE, "evaluation.json"), "r", encoding="utf-8"))
    assets = load_assets()

    results = []
    for item in manifest["items"]:
        iid = item["id"]
        qid = item.get("question_id", iid)
        q = assets[qid]
        prompt = q["prompt"]
        grader = build_grader(q)
        max_tokens = q.get("max_tokens", 2048)
        r = c.item(iid, prompt, grader, max_tokens=max_tokens)
        r["question_id"] = qid
        results.append(r)

    out = {"protocol_version": 1, "items": results}
    with open(args.output, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False)


if __name__ == "__main__":
    main()
